/* Typed access to the real menu. menu.json is generated by scripts/gen-menu.mjs from design/data/menu.js:
   regenerate, never edit by hand. */
import raw from "./menu.json" with { type: "json" };

export type TagId = "hit" | "new" | "veg" | "hot" | "out";
export type Course = "starter" | "salad" | "main" | "side" | "sauce" | "dessert" | "drink" | "addon" | "breakfast";
export type AllergenId =
  | "gluten" | "crustaceans" | "eggs" | "fish" | "peanuts" | "soy" | "milk"
  | "nuts" | "celery" | "mustard" | "sesame" | "sulphites" | "lupin" | "molluscs";

export interface Category { id: string; n: string; course: Course }

export interface Dish {
  id: string;
  /** the page address when it differs from the id (cut ids, decision 12.11.2026); otherwise the address is the id */
  slug?: string;
  n: string;          // name
  cat: string;        // category id ("obedno" for lunch items)
  course: Course;
  comp: string;       // composition text ("" when unknown)
  g: string;          // weight / unit text, e.g. "350 гр."
  p: number;          // price in EUR
  lv?: number;        // original price in BGN
  site_eur?: number;
  t: TagId[];         // hit/new are sample tags; veg/hot derived from comp (kitchen confirms)
  al: AllergenId[];   // derived from comp (kitchen confirms)
  noOnion: boolean;
  share: boolean;
  per100?: boolean;   // price is per 100 g (Black Angus steaks)
  priceNote?: string;
  protein?: number;   // nutrition data: not in the data yet
  kcal?: number;
  /* lunch-only fields */
  group?: string;
  lunch?: boolean;
  /** menu editor (15.11.2026): a description under the title, a photo uploaded in the admin (/media/<sha256>.webp|jpg|png;
      a data: URL only in the demo) */
  desc?: string;
  photo?: string;
  /** only in Menu.removed: taken off the menu */
  removed?: boolean;
}

export interface LunchRaw { id: string; group: string; n: string; p: number | null; /** live menu only (api.menu): sold out today */ out?: boolean }

/** "Смени" (a side dish swap, e.g. at the Bertha oven): groups of options with a surcharge or none; hidden until the new menu */
export interface SwapGroup { id: string; n: string; opts: { n: string; p: number }[]; cats: string[] }
/** "Добави" and "Смени" per category and per dish (decision 15.11.2026): the dish wins over its category */
export interface MenuOpts {
  addon: { cats: string[]; dishes: Record<string, boolean> };
  swap: { on: false; groups: SwapGroup[]; dishes: Record<string, string[]> };
}

export interface Menu {
  updated: string;
  source: string;
  cats: Category[];
  items: Dish[];
  lunch: { date: string; dayName: string; items: LunchRaw[] };
  /** the admin's menu settings (missing in the generated menu.json: "Добави" for pizzas and burgers, ORDER_RULES.addonCats) */
  opts?: MenuOpts;
  /** dishes taken off the menu: kept for reference (old orders, the kitchen, a cart), never listed, searched or ordered */
  removed?: Dish[];
  /** old public addresses of the menu -> where they lead now (301), kept by the core on every publish */
  redirects?: Record<string, string>;
}

export const MENU = raw as unknown as Menu;
